import { COUNTRY_FLAGS } from "../pages/AdminPage/components/TipsEditor/countryFlags";

const tips = [
  // Additional tips will be auto-generated by the blog management system,
  {
    id: 1,
    country: "Trinidad and Tobago",
    country_code: "TT",
    state: null,
    path: "trinidad-and-tobago",
    title: "Trinidad and Tobago Travel Tips",
    description: "Essential tips for traveling in Trinidad and Tobago",
    created_at: new Date("2025-07-07"),
  },
  {
    id: 2,
    country: "United States",
    country_code: "US",
    state: "Massachusetts",
    path: "united-states-massachusetts",
    title: "United States, Massachusetts Travel Tips",
    description: "Essential tips for traveling in United States, Massachusetts",
    created_at: new Date("2025-07-22"),
  },
];

// Helper function to find existing tips page
export const findTipsPage = (country, state = null) => {
  return tips.find((tip) => tip.country === country && tip.state === state);
};

// Helper function to generate tips path
export const generateTipsPath = (country, state = null) => {
  const isUSCountry = (countryCode) => countryCode === "US";

  if (state && isUSCountry(getCountryCode(country))) {
    // For US states: /tips/united-states-california
    const serializedState = state.toLowerCase().replace(/[^a-z0-9]/g, "-");
    return `united-states-${serializedState}`;
  } else {
    // For countries: /tips/trinidad-and-tobago
    return country.toLowerCase().replace(/[^a-z0-9]/g, "-");
  }
};

// Helper function to get country code using our comprehensive mapping
const getCountryCode = (country) => {
  // Common variations of country names mapped to their standard form
  const countryVariations = {
    "United States": "US",
    "United States of America": "US",
    USA: "US",
    "U.S.A.": "US",
    America: "US",
    "Trinidad and Tobago": "TT",
    "Trinidad & Tobago": "TT",
    "United Kingdom": "GB",
    UK: "GB",
    "Great Britain": "GB",
  };

  // First try direct mapping
  const code = countryVariations[country];
  if (code) return code;

  // If no direct match, try to find the code by matching the country name
  const entry = Object.entries(COUNTRY_FLAGS).find(([_, flagCode]) => {
    const countryName = country.toLowerCase();
    const flagCountry = flagCode.toLowerCase();
    return (
      countryName === flagCountry ||
      countryName.includes(flagCountry) ||
      flagCountry.includes(countryName)
    );
  });

  return entry ? entry[0] : "";
};

// Helper function to add new tips page
export const addTipsPage = (country, state = null) => {
  const existingTip = findTipsPage(country, state);
  if (existingTip) {
    return existingTip.path;
  }

  const newTip = {
    id: tips.length + 1,
    country,
    country_code: getCountryCode(country),
    state,
    path: generateTipsPath(country, state),
    title: state
      ? `${country}, ${state} Travel Tips`
      : `${country} Travel Tips`,
    description: state
      ? `Essential tips for traveling in ${state}, ${country}`
      : `Essential tips for traveling in ${country}`,
    created_at: new Date(),
  };

  tips.push(newTip);
  return newTip.path;
};

export default tips;
